#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────
#
# Klaviyo's branded sending domain for jeanmanzo.com, so the Escaneo's result
# email is signed by the domain in the From and stops landing in spam. Klaviyo
# guide: https://help.klaviyo.com/hc/en-us/articles/115000357752
# The records go on a subdomain plus one TXT on the root: the MX records of
# jeanmanzo.com (Namecheap forwarding) are not touched. Run from the repo root:
#   bash scripts/setup-klaviyo-dominio.sh

cd "$(dirname "$0")/.."
ROOT_DOMAIN="jeanmanzo.com"
FLOW_NAME="Escaneo: resultado por email"

# ns_ready SUBDOMAIN prints Klaviyo's nameservers once the delegation is public.
ns_ready() { dig +short NS "$1" @1.1.1.1 2>/dev/null | grep -i klaviyo || true; }
txt_ready() { dig +short TXT "$ROOT_DOMAIN" @1.1.1.1 2>/dev/null | grep -i klaviyo || true; }

TOTAL_STAGES=6

banner "Klaviyo: dominio de envío propio"
say "Al final, el correo del Escaneo sale firmado por ${ROOT_DOMAIN} y no por Klaviyo."
note "No se toca el MX de ${ROOT_DOMAIN}: tu reenvío de Namecheap sigue igual."
pause

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Klaviyo: agregar el dominio"
open_url "https://www.klaviyo.com/settings/domains"
step "Si no abre ahí: tu nombre (abajo a la izquierda) → Settings → pestaña Domains."
step "Add domain → Email type: Marketing → Next."
step "Root domain: ${ROOT_DOMAIN} → Next."
step "Sending domain: send → Next."
step "Routing type: Dynamic (Cloudflare acepta registros NS) → Next."
note "Tu dominio ya tiene DMARC, así que Klaviyo no debería ofrecer agregar uno. Si lo ofrece, déjalo apagado."
step "Elige Set up manually (no Entri: así no le das acceso a tu Cloudflare)."
ask SUBDOMAIN "¿Qué subdominio quedó? (Enter para usar send)"
SUBDOMAIN="${SUBDOMAIN:-send}"
SENDING_DOMAIN="${SUBDOMAIN}.${ROOT_DOMAIN}"
say "Deja esa pantalla de Klaviyo abierta: tiene los 5 registros."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: los 4 registros NS"
open_url "https://dash.cloudflare.com/?to=/:account/${ROOT_DOMAIN}/dns/records"
step "En ${ROOT_DOMAIN} → DNS → Records, haz clic en Add record 4 veces, uno por cada NS de Klaviyo:"
note "    Type: NS · Name: ${SUBDOMAIN} · Nameserver: el valor que muestra Klaviyo (ns1…ns4) · TTL: Auto"
note "Usa los valores exactos de tu pantalla de Klaviyo, que pueden variar por región."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: el TXT de verificación"
step "Add record una vez más:"
note "    Type: TXT · Name: @ · Content: el valor TXT que muestra Klaviyo · TTL: Auto"
warn "Es un registro TXT nuevo. No edites el TXT del SPF (v=spf1…) ni el de Google."
warn "No toques los registros MX."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Esperar a que el DNS se publique"
say "Reviso cada 10 segundos. Con Cloudflare suele tardar entre 1 y 5 minutos."
note "Ctrl+C para cortar; puedes volver a correr el wizard después."
until [[ -n "$(ns_ready "$SENDING_DOMAIN")" && -n "$(txt_ready)" ]]; do
  printf '  %s…%s NS %s · TXT %s\r' "$DIM" "$RESET" \
    "$([[ -n "$(ns_ready "$SENDING_DOMAIN")" ]] && echo listo || echo esperando)" \
    "$([[ -n "$(txt_ready)" ]] && echo listo || echo esperando)"
  sleep 10
done
printf '\n  %s✓%s %s delega en Klaviyo y el TXT de verificación ya es público\n' "$GREEN" "$RESET" "$SENDING_DOMAIN"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Klaviyo: verificar y activar"
step "En la pantalla de los registros, haz clic en Verify y luego en Finish."
step "En Settings → Domains espera el estado Verified. Si dice Verifying, recarga en unos minutos."
note "Klaviyo recomienda pausar los envíos al activar el primer dominio de marketing."
step "Pon el flow \"${FLOW_NAME}\" en Manual."
step "En la fila del dominio haz clic en Activate y confírmalo en el diálogo."
note "Si te ofrece opciones de calentamiento, elige moverlo todo de una vez: el volumen es de un correo por lead."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "El remitente y la prueba"
ask SENDER_EMAIL "¿Qué dirección @${ROOT_DOMAIN} usas de remitente? (Enter para hola@${ROOT_DOMAIN})"
SENDER_EMAIL="${SENDER_EMAIL:-hola@${ROOT_DOMAIN}}"
note "Debe ser una dirección que tu reenvío de Namecheap ya te haga llegar."
note "No uses @${SENDING_DOMAIN}: ese subdominio no recibe correo."
step "En el email del flow: Sender email ${SENDER_EMAIL}. Sender name y Reply-to se quedan como están."
step "Vuelve a poner el flow en Live."
open_url "https://jeanmanzo.com/es/operar-a-mano/"
step "Haz un Escaneo y desbloquéalo con tu email."
step "Cuando llegue: ⋮ → Mostrar original. SPF, DKIM y DMARC deben decir PASS."
if confirm "¿Llegó a la bandeja de entrada con DKIM y DMARC en PASS?"; then
  printf '  %s✓%s el correo sale firmado por %s\n' "$GREEN" "$RESET" "$ROOT_DOMAIN"
else
  SKIPPED+=("Pégale a Claude el bloque de Mostrar original (SPF, DKIM, DMARC) para revisarlo")
fi
pause

finish
